interface Run { directory:string; database:string; user:string; password:string; pgPort:number }
function ownedRun():Run {
  const manifest=process.env.BOOT02_RUN_FILE;if(!manifest)throw new Error('Use owned integration runner');
  const file=fs.realpathSync(manifest),dir=path.dirname(file),stat=fs.statSync(file);
  if(path.dirname(dir)!==fs.realpathSync(os.tmpdir())||!path.basename(dir).startsWith('growdesk-integration-')||stat.uid!==process.getuid?.()||(stat.mode&0o077))throw new Error('Unsafe integration manifest');
  const run=JSON.parse(fs.readFileSync(file,'utf8')) as Run;if(run.directory!==dir||!run.database.startsWith('test_')||!run.user.startsWith('test_'))throw new Error('Not an owned database');return run;
}
async function register(app:ReturnType<typeof buildApiApp>,name:string){
  const response=await app.inject({method:'POST',url:'/api/v1/auth/register',payload:{username:`test_chat_${name}_${randomUUID()}`,password:'Test_chat_password_123!',displayName:`test_chat_${name}`}});
  assert.equal(response.statusCode,201,response.payload);return response.json<{data:{user:{id:string};accessToken:string}}>().data;
}
test('durable chat preserves ownership, retries, confirmation atomicity and cancellation fences',async t=>{
  const run=ownedRun(),url=requireTestDatabaseUrl(`postgresql://${run.user}:${run.password}@127.0.0.1:${run.pgPort}/${run.database}?sslmode=disable`,{host:'127.0.0.1',port:run.pgPort,database:run.database,role:run.user,password:run.password});
  const db=createDatabaseContext({url}),app=buildApiApp({databaseContext:db,jwtSecret:'test_chat_secret_at_least_32_characters'});
  const previous={provider:process.env.GROWDESK_AI_PROVIDER,fixture:process.env.GROWDESK_AI_FIXTURE_RESPONSE,node:process.env.NODE_ENV};process.env.NODE_ENV='test';process.env.GROWDESK_AI_PROVIDER='fixture';process.env.GROWDESK_AI_FIXTURE_RESPONSE=JSON.stringify({text:'test answer',actions:[]});
  t.after(async()=>{for(const [key,value] of Object.entries(previous)){const name=key==='provider'?'GROWDESK_AI_PROVIDER':key==='fixture'?'GROWDESK_AI_FIXTURE_RESPONSE':'NODE_ENV';if(value===undefined)delete process.env[name];else process.env[name]=value;}await app.close();await db.close();});
  const a=await register(app,'a'),b=await register(app,'b');const ha={authorization:`Bearer ${a.accessToken}`},hb={authorization:`Bearer ${b.accessToken}`};
  const families=(await app.inject({method:'GET',url:'/api/v1/families',headers:ha})).json<{data:Array<{id:string}>}>().data;const familyId=families[0]!.id;
  const babyRes=await app.inject({method:'POST',url:`/api/v1/families/${familyId}/babies`,headers:ha,payload:{name:'test_chat_baby',gender:'other',birthDate:'2026-01-01'}});const babyId=babyRes.json<{data:{id:string}}>().data.id;
  const session=await app.inject({method:'POST',url:'/api/v1/web/ai/sessions',headers:ha,payload:{babyId,title:'test chat'}});assert.equal(session.statusCode,201,session.payload);const sessionId=session.json<{data:{id:string}}>().data.id;
  const service=new DurableChatService(db.prisma,db.pool);const principal:UserPrincipal={userId:a.user.id,username:'test_chat_a',familyMemberships:[{userId:a.user.id,familyId,role:'owner',status:'active'}],babyMemberships:[{userId:a.user.id,familyId,babyId,role:'owner',status:'active'}]};
  await t.test('create is idempotent by stable clientMessageId and rejects changed input',async()=>{
    const id=randomUUID(),body={clientMessageId:id,message:'test message',attachmentIds:[]};const first=await service.create(principal,sessionId,body);const replay=await service.create(principal,sessionId,body);assert.equal(first.data.id,replay.data.id);
    await assert.rejects(service.create(principal,sessionId,{...body,message:'changed'}),e=>(e as any).code==='MESSAGE_ID_REUSED');
    assert.equal(Number((await db.pool.query('SELECT count(*) FROM task_executions WHERE id=$1',[first.data.id])).rows[0].count),1);
  });
  let failedRun='';
  await t.test('foreign user cannot read or mutate a run',async()=>{const body={clientMessageId:randomUUID(),message:'foreign test',attachmentIds:[]};const created=await service.create(principal,sessionId,body);failedRun=created.data.id;await assert.rejects(service.get(b.user.id,failedRun),e=>(e as any).code==='RUN_NOT_FOUND');await assert.rejects(service.cancel(b.user.id,failedRun),e=>(e as any).code==='RUN_NOT_FOUND');});
  await t.test('explicit retry is idempotent and does not increment the attempt before worker claim',async()=>{
    await db.pool.query("UPDATE task_executions SET status='failed',attempt=1,max_attempts=1 WHERE id=$1",[failedRun]);const command=randomUUID();const one=await service.retry(a.user.id,failedRun,command),two=await service.retry(a.user.id,failedRun,command);assert.deepEqual(one,two);const row=(await db.pool.query('SELECT status,attempt,max_attempts FROM task_executions WHERE id=$1',[failedRun])).rows[0];assert.equal(row.status,'queued');assert.equal(row.attempt,1);assert.equal(row.max_attempts,2);assert.equal(Number((await db.pool.query('SELECT count(*) FROM task_outbox WHERE aggregate_id=$1 AND phase_key LIKE 'retry:%'',[failedRun])).rows[0].count),1);
  });
  await t.test('cancel increments fencing token and prevents stale publication',async()=>{
    await db.pool.query("UPDATE task_executions SET status='running',lease_owner='test_worker',lease_expires_at=clock_timestamp()+interval '1 minute',fence_token=8 WHERE id=$1",[failedRun]);await service.cancel(a.user.id,failedRun);const row=(await db.pool.query('SELECT status,fence_token,lease_owner FROM task_executions WHERE id=$1',[failedRun])).rows[0];assert.equal(row.status,'cancelled');assert.equal(String(row.fence_token),'9');assert.equal(row.lease_owner,null);
  });
  await t.test('confirmation executes selected actions inside one transaction and is replay safe',async()=>{
    const message=randomUUID();const created=await service.create(principal,sessionId,{clientMessageId:message,message:'propose',attachmentIds:[]});const runId=created.data.id;const action1=randomUUID(),action2=randomUUID();const actions=[{actionId:action1,entityType:'feeding',operation:'create',summary:'one',payload:{feedingType:'formula',amountMl:'90',occurredAt:'2026-09-15T01:00:00Z'}},{actionId:action2,entityType:'feeding',operation:'create',summary:'two',payload:{feedingType:'invalid',amountMl:'90',occurredAt:'2026-09-15T02:00:00Z'}}];
    const canonical=(await import('@growdesk/contracts')).canonicalJsonStringify;const {createHash}=await import('node:crypto');const hash=createHash('sha256').update(canonical(actions)).digest('hex');await db.pool.query("UPDATE task_executions SET status='awaiting_confirmation' WHERE id=$1",[runId]);await db.pool.query('UPDATE ai_runs SET proposed_plan=$2::jsonb WHERE id=$1',[runId,JSON.stringify({actions,planHash:hash,expiresAt:new Date(Date.now()+60000).toISOString()})]);
    await assert.rejects(service.confirm(principal,runId,{planHash:hash,actionIds:[action1,action2]}));assert.equal(Number((await db.pool.query('SELECT count(*) FROM feeding_records WHERE baby_id=$1',[babyId])).rows[0].count),0,'first write rolled back when second action failed');
    actions[1]={...actions[1],payload:{feedingType:'formula',amountMl:'100',occurredAt:'2026-09-15T02:00:00Z'}};const goodHash=createHash('sha256').update(canonical(actions)).digest('hex');await db.pool.query('UPDATE ai_runs SET proposed_plan=$2::jsonb WHERE id=$1',[runId,JSON.stringify({actions,planHash:goodHash,expiresAt:new Date(Date.now()+60000).toISOString()})]);const body={planHash:goodHash,actionIds:[action1,action2]};assert.equal((await service.confirm(principal,runId,body)).data.appliedActionCount,2);assert.equal((await service.confirm(principal,runId,body)).data.appliedActionCount,2);assert.equal(Number((await db.pool.query('SELECT count(*) FROM feeding_records WHERE baby_id=$1',[babyId])).rows[0].count),2);
  });
  await t.test('revoked baby membership invalidates existing run reads',async()=>{await db.pool.query("UPDATE baby_members SET status='revoked' WHERE user_id=$1 AND baby_id=$2",[a.user.id,babyId]);await assert.rejects(service.get(a.user.id,failedRun),e=>(e as any).code==='BABY_NOT_FOUND');});
